(()=>{'use strict';const root=document.querySelector('.home-graphical'),box=document.getElementById('home-info');if(!root||!box)return;const desktop=matchMedia('(min-width:1280px) and (hover:hover) and (pointer:fine)');let active=null,restore=null;const reading=document.querySelector('[data-reading-options]');
function placeReading(){const target=!desktop.matches||document.body.classList.contains('home-text-mode')?document.querySelector('.home-classic .header-tools'):root.querySelector('.header-tools');if(reading&&target&&reading.parentElement!==target)target.prepend(reading);}placeReading();
const closeButton=box.querySelector('.home-info-close'),title=box.querySelector('[data-home-info-title]'),copy=box.querySelector('[data-home-info-text]'),search=box.querySelector('[data-home-search-links]'),plusBadge=box.querySelector('[data-home-plus-badge]'),featureLabel=box.querySelector('[data-home-feature-label]');
function close(focus=false){if(!active)return;const previous=active;active.setAttribute('aria-expanded','false');active=null;box.hidden=true;if(focus)previous.focus();}
function position(){if(!active||box.hidden)return;const r=active.getBoundingClientRect(),gap=10,pad=12;box.style.left='12px';box.style.top='12px';const b=box.getBoundingClientRect(),vw=document.documentElement.clientWidth,vh=window.innerHeight;let x=r.right+gap,y=r.top;if(x+b.width>vw-pad)x=r.left-b.width-gap;if(x<pad)x=Math.max(pad,Math.min(r.left,vw-b.width-pad));if(y+b.height>vh-pad)y=vh-b.height-pad;box.style.left=Math.max(pad,x)+'px';box.style.top=Math.max(pad,y)+'px';}
root.addEventListener('click',e=>{const trigger=e.target.closest('[data-home-help],[data-home-search]');if(!trigger)return;e.preventDefault();e.stopPropagation();if(active===trigger){close(true);return;}close();active=trigger;title.textContent=trigger.hasAttribute('data-home-search')?'Search Gold Trails':trigger.getAttribute('aria-label').replace(/^About /,'');const premium=trigger.dataset.homePremium==='plus';plusBadge.hidden=!premium;featureLabel.hidden=!premium;copy.textContent=trigger.dataset.homeHelp||'';copy.hidden=trigger.hasAttribute('data-home-search');search.hidden=!trigger.hasAttribute('data-home-search');box.hidden=false;trigger.setAttribute('aria-expanded','true');position();closeButton.focus();});
closeButton.addEventListener('click',()=>close(true));document.addEventListener('pointerdown',e=>{if(active&&!box.contains(e.target)&&!active.contains(e.target))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();close(true);}});window.addEventListener('resize',()=>{placeReading();if(active&&!active.getClientRects().length)close();else position();});window.addEventListener('scroll',position,{passive:true});
function textView(focus=true){if(restore||!desktop.matches)return;close();document.body.classList.add('home-text-mode');placeReading();restore=document.createElement('button');restore.type='button';restore.textContent='Return to illustrated homepage';restore.className='gold-button home-return-art';restore.style.margin='16px';restore.addEventListener('click',()=>{document.body.classList.remove('home-text-mode');placeReading();restore.remove();restore=null;root.querySelector('.home-hotspot').focus();});document.querySelector('.home-classic').prepend(restore);if(focus){const heading=document.querySelector('.home-classic h1');if(heading){heading.tabIndex=-1;heading.focus();}}}
root.querySelector('[data-home-text-view]').addEventListener('click',()=>textView());
// Raster lettering cannot change weight/size. The existing readable HTML view can.
const typeChanged=()=>{const r=document.documentElement;if(r.dataset.readingSize!=='0'||['bold','contrast','roomy','font'].some(k=>r.hasAttribute('data-reading-'+k)))textView(false);};typeChanged();new MutationObserver(typeChanged).observe(document.documentElement,{attributes:true,attributeFilter:['data-reading-size','data-reading-bold','data-reading-contrast','data-reading-roomy','data-reading-font']});})();
